import{_ as a,o as t,c as n,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"Parallels Between VLA Model Post-Training and Human Motor Learning: Progress, Challenges, and Trends","description":"","frontmatter":{"title":"Parallels Between VLA Model Post-Training and Human Motor Learning: Progress, Challenges, and Trends","arxiv":"2506.20966","date":"2025-06-26","authors":"Tian-Yu Xiang, Ao-Qun Jin, Xiao-Hu Zhou, Mei-Jiang Gui, Xiao-Liang Xie, Shi-Qi Liu, Shuang-Yi Wang, Sheng-Bin Duan, Fu-Chao Xie, et al.","categories":"cs.RO, cs.AI","topics":"通用具身智能, VLA 后训练, 综述","outline":[2,2]},"headers":[],"relativePath":"papers/2506.20966.md","filePath":"papers/2506.20966.md","lastUpdated":null}'),o={name:"papers/2506.20966.md"};function p(l,s,r,i,m,g){return t(),n("div",null,[...s[0]||(s[0]=[e('<h1 id="parallels-between-vla-model-post-training-and-human-motor-learning-progress-challenges-and-trends" tabindex="-1">Parallels Between VLA Model Post-Training and Human Motor Learning: Progress, Challenges, and Trends <a class="header-anchor" href="#parallels-between-vla-model-post-training-and-human-motor-learning-progress-challenges-and-trends" aria-label="Permalink to &quot;Parallels Between VLA Model Post-Training and Human Motor Learning: Progress, Challenges, and Trends&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2506.20966" target="_blank" rel="noreferrer">2506.20966</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-06-26</td></tr><tr><td><strong>作者</strong></td><td>Tian-Yu Xiang, Ao-Qun Jin, Xiao-Hu Zhou, Mei-Jiang Gui, Xiao-Liang Xie, Shi-Qi Liu, Shuang-Yi Wang, Sheng-Bin Duan, Fu-Chao Xie, et al.</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>借 Newell 的约束主导技能获取理论，把 VLA 后训练方法按环境感知、本体感知、任务理解与多组件整合四类重组，并在每一类里对照人类运动学习的对应机制给出研究方向。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文按 arXiv abs 页给出的 <strong>v2</strong>（2026-01-29 修订）全文撰写；v1 提交于 2025-06-26。frontmatter 日期用 v1 提交日。作者共 14 位，取前 9 位 + et al.</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLA 模型的&quot;开箱即用&quot;能力远不如语言模型。作者给出的三条结构性原因很具体：其一，最大的开源机器人操作数据集约 250 万条演示，比大模型时代之前的 NLP 语料（GPT-2 的 800 万网页）还小；其二，机器人本体的正逆动力学差异巨大，且同一任务在同一初始条件下的执行方式有无穷多种，而语言在语义确定后表达方式相对受限；其三，操作任务依赖高度抽象、难以泛化的规则。这三条共同导致预训练之后必须有一个适配阶段，即 post-training。</p><p>真正需要被解答的问题不是&quot;要不要后训练&quot;，而是&quot;后训练该沿哪些轴做&quot;。这篇综述的答案来自运动行为学：Newell 的约束主导框架把人类动作的形成归结为<strong>任务约束、环境约束、机体约束</strong>三者的交互。作者主张这三条约束与机器人后训练的三个维度一一对应——环境（提升感知）、本体（精确建模自身动力学）、任务（注入操作先验），并据此组织 129 篇文献。这个映射的价值在于它提供了一个&quot;缺口清单&quot;：给定一个失败的 VLA 部署，你可以逐轴问是感知不够、本体建模不准，还是任务理解不到位。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>已有的 VLA 综述大致分三类。一类做整体回顾，梳理演化脉络与未来方向；一类聚焦具体切面，例如机器人泛化能力的评测分类法、迁移学习策略、真实应用落地；还有一类是更宽的机器人基础模型综述。它们各自能做到的事很清楚：给出领域地图、给出模型清单。</p><p>不够在哪里？作者的论证是精确的：现有的&quot;后训练&quot;综述几乎全部针对语言模型；而机器人侧最接近的一篇只覆盖迁移学习，而迁移学习只是后训练谱系里的一个子集（后训练还包含偏好对齐、安全约束、在线 RL 等）。也就是说，缺口不是&quot;没人写过 VLA 综述&quot;，而是&quot;没人把 VLA 特有的后训练手段单独抽出来、并给出一个有解释力的组织轴&quot;。这里可以补一句背景：后训练之所以在 VLA 上比在 LLM 上更关键，是因为 VLA 的泛化能力本身就弱于语言与视觉模型，适配的边际收益更大。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>把本文自己的贡献放到一边，只用 2025 年中之前的既有认识，可以还原出这条路径。首先，一个诚实的观察是：VLA 后训练的方法列表看起来杂乱无章——有人加深度图，有人换扩散动作头，有人加 CoT 推理，有人上 RL，有人做数据筛选。按&quot;技术手段&quot;分类只会得到一张平铺的清单，没有解释力。</p><p>其次，需要一个不来自方法本身的组织轴。作者所在的实验室背景（中科院自动化所，长期做医疗机器人与神经科学交叉）提示了一个候选：人类学习运动技能时，研究者早已面临同样的分类困难，而 Newell 在 1986 年给出的答案是三类约束。这个框架的吸引力在于它是<strong>按约束来源</strong>而非按方法分类的，因此天然对应&quot;这个后训练手段在弥补哪一类缺陷&quot;。</p><p>第三步是检验这个映射是否真的落得下去。加深度、加点云、加触觉 → 环境约束；学正逆运动学、改动作头 → 机体约束；层次化任务分解、人机交互纠正 → 任务约束；RL、视觉交互预测、数据筛选同时改多个轴 → 单列一类&quot;多组件整合&quot;。这个第四类的存在本身说明作者意识到三分法不是良分割（见 §9）。最后，为了让综述有可复核性，作者采用了 PRISMA 式的检索—筛选流程，而不是凭印象选文献。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>VLA 后训练的方法之所以看起来杂乱，是因为大家在按&quot;用了什么技术&quot;分类；换成按&quot;在补哪一类约束的缺口&quot;分类，杂乱就消失了。人类运动技能的形成早就有一个现成的三约束框架（任务、环境、机体），把它借过来，既能组织现有方法，又能反向指出哪一类缺口还没人补。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>综述本身的&quot;pipeline&quot;是文献检索与组织流程，作者写得相当规范。</p><p><strong>检索</strong>（2025 年 8 月 31 日执行）：在 IEEE Xplore、ACM DL、Web of Science Core Collection、Scopus、ScienceDirect、Google Scholar 六个库检索，检索式为 <code>(&quot;vision-language-action&quot; OR &quot;VLA&quot;) AND (&quot;robotic manipulation&quot; OR &quot;task execution&quot;) AND (&quot;fine-tuning&quot; OR &quot;model adaptation&quot; OR &quot;post-training&quot;)</code>，命中 997 条记录。</p><p><strong>筛选</strong>：三位评审独立读标题、摘要、全文，剔除非 VLA 操作类、以及主题为预训练/架构设计/基准/二次综述的论文。三人一致纳入的 95 条直接进入，两人纳入的 71 条讨论后定夺，最终留下 129 篇。三人各自保留 160 / 307 / 133 条，一致性为 Cohen&#39;s Kappa 0.48 / 0.62 / 0.44，Fleiss&#39;s Kappa 0.49，百分比一致率 0.81 / 0.91 / 0.80。</p><p><strong>组织</strong>：四大类，每类先给一节&quot;人类对应策略&quot;再给方法小节。</p><ul><li><strong>环境感知</strong>（表 I）：affordance 引导学习、面向操作的编码器增强、面向操作的表示增强。</li><li><strong>本体感知</strong>（表 II）：正逆运动学学习、动作头设计。</li><li><strong>任务理解</strong>（表 III）：人机交互、层次化任务操作。</li><li><strong>多组件整合</strong>（表 IV）：强化学习、视觉交互预测、主动数据处理。</li></ul><p><strong>综合评测</strong>（第五节）：把表 V（LIBERO）与表 VI（CALVIN）里各方法的公开数字汇总，按后训练手段类型读出趋势，再提炼成五条 takeaway。<strong>挑战与趋势</strong>（第六节）：四个大类共十个小节，每个小节的写法固定为&quot;当前问题 → 近期尝试 → 人类运动学习中的对应机制 → 由此导出的三条具体建议&quot;。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>综述没有自己跑实验，其&quot;实验&quot;是对两个基准上公开数字的二次分析。</p><p><strong>LIBERO（表 V）</strong>。十六个月内平均成功率从约 75% 升到 98%；除长时程 suite 外，其余三个 suite 的 SOTA 都已超过 98%，因此剩余空间几乎全在长时程。按后训练手段拆：动作头设计是最&quot;即插即用&quot;的一类，OpenVLA 通过并行解码、动作分块与连续输出（即 OpenVLA-OFT）把平均从 76.5% 提到 94.5%；显式引入额外模态或时序记忆同样有效，3D-CAVLA 用点云几何拿到全表最好的 98.1%，MemoryVLA 用历史特征记忆缓冲拿到 96.7%。相反，RL 类后训练在 LIBERO 榜上仍落后于最好的监督式后训练；层次化策略（如 CLIP-RT）早期的优势在近期榜单上不明显，作者推测是因为当前基准的难度不足以体现层次结构的价值。</p><p><strong>CALVIN（表 VI）</strong>。平均成功序列长度从约 3.5 升到 4.3–4.4；按指令长度拆，长度为 1 的成功率从 89.7% 升到 98.2%，长度为 5 的从 31.5% 升到 78.1%——增益集中在长程端，但长程仍是瓶颈。一个与 LIBERO 相反的结论：单纯叠加感知模态在 CALVIN 上收效有限，例如引入深度信息的 RoboFlamingo-Plus 提升不大；作者的解释是 CALVIN 更强调长程序列化，而表示层的增强只帮低层操作。CALVIN 上真正有效的方向是视觉交互预测（DreamVLA、VPP）与 RL 后训练。</p><p><strong>五条 takeaway</strong>：精心设计的后训练（动作头 + 目标函数选择）能大幅抬升骨干性能；3D/触觉等表示增强改善短程但对长程有限，需与世界建模或层次控制配合；预测未来观测或潜动力学有利于长程且易与现有 VLA 集成；RL 与层次化任务操作仍被低估，推荐的最小流水线是&quot;高层语言/视觉规划头 + 低层 VLA 执行器 + 演示与回放上的离线 BC/RLPD + 带奖励与安全约束的在线 RL&quot;；基准设计应转向更长的时程、部分可观测与组合泛化。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：VLA 后训练方法可以按 Newell 的三类约束重组为环境感知、本体感知、任务理解，加上一类跨轴的多组件整合，共四类。检索 997 条、三评审筛选后纳入 129 篇，一致性为 Fleiss&#39;s Kappa 0.49。二次分析两个基准的结论是：动作头设计是性价比最高的通用手段，3D/触觉表示增强帮短程不帮长程，未来观测预测帮长程，RL 与层次化仍待开发。十个挑战小节的统一写法是&quot;人类怎么解决这件事 → VLA 该怎么做&quot;，其中最实的三条是评测协议（种子控制与统计功效）、多模态融合（含模态丢弃训练）、以及安全的硬约束与运行时监控。作者自陈本文不深入技术实现细节，定位是导览与设计参考。</p><p><strong>三句话版</strong>：用运动行为学的三约束框架给 VLA 后训练建立一个按&quot;缺口来源&quot;而非&quot;技术手段&quot;的分类法。在 LIBERO/CALVIN 上的二次分析给出可操作的排序：动作头 &gt; 表示增强（短程）、未来预测 &gt; 表示增强（长程）。挑战一节把人类运动学习的机制逐条翻译成后训练建议。</p><p><strong>一句话版</strong>：把&quot;人怎么练技能&quot;当作 VLA 后训练的分类学与研究议程生成器。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>跨研究汇总的基准数字，其排序是可信的，因而可以据此提炼&quot;可操作的指南&quot;。</strong> 这一条一旦不成立，第五节的全部结论（也是本文最有实用价值的部分）就同时失效。</p><p>而否证这条假设的证据，恰恰由本文自己在第六节 VI-A1 给出：作者明确写道，仿真基准只能消除部分方差，因为各研究的超参与环境随机化设定不同；并援引报道称<strong>随机种子导致的成功率波动可超过 30%</strong>。把这两处并排看会很尴尬——§V-B 用 98.1%（3D-CAVLA）与 96.7%（MemoryVLA）的 1.4 个百分点之差来支撑&quot;点云几何优于时序记忆&quot;，而作者自己刚说过同一方法换个种子可能差 30 个百分点。同样地，&quot;OpenVLA 76.5% → OpenVLA-OFT 94.5%&quot;这一条因为幅度足够大而可信，但&quot;RL 类落后于监督式后训练&quot;这一结论所依赖的差距要小得多，很可能落在噪声里。</p><p>作者提供的部分缓解是只提取大幅度趋势（十六个月 75%→98%、长度为 5 的任务 31.5%→78.1%）。缺失的证据是：表 V/VI 没有报告任何一项的重复次数、随机种子数或置信区间，也没有对&quot;同一方法在不同论文中被报告的数值&quot;做一致性检查。因此，凡是幅度小于 5 个百分点的比较，都应被视为不可用。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，且完全不需要机器人。<strong>目标：给这篇综述的表 V 补上它缺的误差棒。</strong></p><p>选 LIBERO 上三个有公开代码与权重的代表方法，分别来自本文的三个不同类别：一个动作头设计类（OpenVLA-OFT）、一个表示增强类（任意带点云或历史记忆的开源实现）、一个基线（OpenVLA）。对每个方法，固定训练配方，只改随机种子跑 5 次，每次在四个 suite 上各评 500 个 episode，报告均值与 95% 置信区间。</p><p><strong>支持综述的结果</strong>：三者的置信区间互不重叠，且排序与表 V 一致——那么第五节的排序分析成立，&quot;动作头 &gt; 表示增强&quot;是真实信号。<strong>反驳综述的结果</strong>：置信区间大面积重叠（尤其是同类内部差 1–3 个百分点的条目），或者复现值与原论文报告值系统性偏低——那么表 V 应当被降级为&quot;方法清单&quot;而非&quot;排序依据&quot;，第五节的四条 takeaway 中至少前两条需要撤回。</p><p>这个实验的价值超出本文本身：LIBERO 上的可复现方差目前是整个 VLA 社区的公共未知量，而它决定了近两年上百篇论文的结论有多少是真的。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>攻击点：四分类法并非良分割，第四类&quot;多组件整合&quot;的存在本身就是证据。</strong> 作者列在这一类下的强化学习、视觉交互预测与主动数据处理，恰恰是第五节判定最有效的几条路线之一（&quot;预测未来观测有利于长程&quot;）。也就是说，最有解释力的方法都落在了&quot;不属于任何单一约束&quot;的兜底类里，而三约束框架对它们没有提供任何分类信息。这削弱了&quot;Newell 框架比按技术手段分类更有解释力&quot;这一核心主张——如果最重要的方法都要靠兜底类容纳，那么分类法的信息量主要体现在剩下的部分。</p><p>进一步，作者自己在 II-C 承认&quot;全参数监督微调同时增强环境感知与注入任务先验&quot;，即三个轴在最常用的后训练手段上是完全纠缠的。一个可判决的检验是：请三位独立标注者按三约束把 129 篇论文各自归类，计算一致性。若一致性显著低于本文筛选阶段的 Fleiss&#39;s Kappa 0.49，则该分类法在操作层面不可复现，其&quot;提供缺口清单&quot;的功能也就无从谈起。</p><p><strong>第二个替代解释</strong>：本文观察到的&quot;十六个月内 LIBERO 从 75% 到 98%&quot;被归因于后训练技术进步，但同期发生的还有骨干规模增大、预训练语料扩张（OXE 之后的多个大规模数据集）、以及评测协议的悄然放松（例如是否使用腕部相机、是否使用状态输入、是否取多个 checkpoint 的最好值）。本文的表 V 未按观测空间分层，因此无法排除&quot;进步主要来自可用观测变多&quot;。CronusVLA 一类论文已经在表格里显式区分 Type I（仅第三人称 + 指令）与 Type II（加状态与腕部视角），本综述若采用同样的分层，第五节的结论可能会明显改变。</p><p><strong>第三，检索式本身会造成系统性遗漏</strong>：检索式要求标题/摘要中出现 &quot;VLA&quot; 或 &quot;vision-language-action&quot; 并同时出现 fine-tuning 类词。大量做 VLA 后训练但自称&quot;policy adaptation&quot;&quot;continual learning&quot;&quot;RLHF for robots&quot;的工作会被漏掉，而这些恰好集中在作者认为&quot;仍待开发&quot;的 RL 与层次化方向。因此&quot;RL 后训练仍未被充分探索&quot;这一结论，部分可能是检索式的产物而非领域现状。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：本文的两半是脱节的。第四节的分类法是描述性的，第六节的人类机制类比是启发式的，两者都无法给出任何<strong>可证伪的预测</strong>。而第九节指出的评测可复现性问题，使得任何基于当前榜单的归纳都站不住。真正缺的不是又一个分类轴，而是一种能把&quot;这个后训练手段补的是哪一类缺口&quot;变成可测量量的方法。</p><p><strong>(b) 可借鉴的相邻领域</strong>：临床康复医学的<strong>运动功能量表</strong>与心理测量学的<strong>多维项目反应理论</strong>。康复医学面对的问题结构与此完全同构——同一位患者的运动障碍可能源于感觉输入、肌骨执行或运动计划，临床上不是靠观察疗法种类来分类，而是靠一组<strong>设计过的诊断动作</strong>分别激发三条通路，从而定位缺口（例如闭眼站立测本体感觉、指鼻测运动计划）。把这个思路搬过来：不要问&quot;这个方法属于哪一类&quot;，而是问&quot;这个模型在三条诊断轴上各得几分&quot;。</p><p><strong>(c) 第一个实验长什么样</strong>：设计一套 <strong>VLA 运动功能量表</strong>——三组各约 10 个任务，每组只在一条约束上施加压力而尽量控制另外两条。环境轴：同一任务、同一本体、只做透明/反光/低光/杂乱等感知退化；本体轴：同一任务、同一场景、只换末端执行器几何或关节限位（要求策略在线适应）；任务轴：同一场景、同一本体、只把指令改成需要组合或条件判断的形式。每个模型输出一个三维画像 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">mb</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，并强制报告 5 个种子的置信区间。</p><p>第一批可报告的结果是：现有后训练方法的增益在三维画像上是否真的按本文预期的方式定向（例如点云方法只涨 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、动作头设计只涨 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">mb</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）。若定向性成立，本文的分类法就从描述升级为可测量的诊断工具；若不成立（例如所有方法都主要涨 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>），那么整个约束分解在 VLA 上就不是正确的抽象，这本身是比再写一篇综述更有价值的负结果。</p>',53)])])}const c=a(o,[["render",p]]);export{h as __pageData,c as default};
